@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix : <http://www.example.org/ontology#> .

<http://www.example.org/ontology/story1>
    a owl:Ontology ;
    rdfs:label "EDIFACT INVOIC Ontology for Industrial Procurement" ;
    rdfs:comment "A deep, richly structured OWL ontology modeling EDIFACT D96A INVOIC messages, roles, and business document structure for industrial procurement, aligned with P2P-O and EN 16931-1." .

#################################################################
# CLASSES
#################################################################
:InterchangeEnvelope a owl:Class ;
    rdfs:label "Interchange Envelope" ;
    rdfs:comment "The envelope that contains one or more EDIFACT messages." .

:Message a owl:Class ;
    rdfs:label "Message" ;
    rdfs:comment "A digital business message, such as INVOIC, contained within an Interchange Envelope." .

:Invoice a owl:Class ;
    rdfs:label "Invoice" ;
    rdfs:comment "An invoice message, conforming to the EDIFACT INVOIC standard and EN 16931-1." ;
    rdfs:subClassOf :Message .

:Segment a owl:Class ;
    rdfs:label "Segment" ;
    rdfs:comment "A segment within an EDIFACT message, e.g., BGM, NAD." .

:BGM_Segment a owl:Class ;
    rdfs:label "BGM Segment" ;
    rdfs:comment "Beginning of Message segment for document identification." ;
    rdfs:subClassOf :Segment .

:NAD_Segment a owl:Class ;
    rdfs:label "NAD Segment" ;
    rdfs:comment "Name and Address segment for participant details." ;
    rdfs:subClassOf :Segment .

:CompositeDataElement a owl:Class ;
    rdfs:label "Composite Data Element" ;
    rdfs:comment "A composite data element in a segment, grouping related simple elements." .

:SimpleDataElement a owl:Class ;
    rdfs:label "Simple Data Element" ;
    rdfs:comment "A simple data element, representing atomic values in a segment." .

:HeaderSection a owl:Class ;
    rdfs:label "Header Section" ;
    rdfs:comment "The header section of an invoice, containing dates and reference numbers." ;
    rdfs:subClassOf :CompositeDataElement .

:DetailSection a owl:Class ;
    rdfs:label "Detail Section" ;
    rdfs:comment "The detail section of an invoice, listing line items." ;
    rdfs:subClassOf :CompositeDataElement .

:SummarySection a owl:Class ;
    rdfs:label "Summary Section" ;
    rdfs:comment "The summary section of an invoice, providing totals such as tax and invoice amount." ;
    rdfs:subClassOf :CompositeDataElement .

:Organization a owl:Class ;
    rdfs:label "Organization" ;
    rdfs:comment "An organization involved in the invoice process, e.g., buyer, supplier, delivery party." .

:AgentRole a owl:Class ;
    rdfs:label "Agent Role" ;
    rdfs:comment "A role played by an organization within an invoice context." .

:BuyerRole a owl:Class ;
    rdfs:label "Buyer Role" ;
    rdfs:comment "The role of buyer in an invoice transaction." ;
    rdfs:subClassOf :AgentRole .

:DeliveryPartyRole a owl:Class ;
    rdfs:label "Delivery Party Role" ;
    rdfs:comment "The role of delivery party in an invoice transaction." ;
    rdfs:subClassOf :AgentRole .

:Address a owl:Class ;
    rdfs:label "Address" ;
    rdfs:comment "An address associated with an organization, such as headquarters or warehouse." .

:GlobalLocationNumber a owl:Class ;
    rdfs:label "Global Location Number" ;
    rdfs:comment "A global identifier for an organization location, e.g., GLN." .

:Item a owl:Class ;
    rdfs:label "Item" ;
    rdfs:comment "An item listed in the invoice." .

:Price a owl:Class ;
    rdfs:label "Price" ;
    rdfs:comment "A price associated with an item." .

:Quantity a owl:Class ;
    rdfs:label "Quantity" ;
    rdfs:comment "A quantity of an item." .

:Tax a owl:Class ;
    rdfs:label "Tax" ;
    rdfs:comment "A tax amount applicable to an item or invoice." .

:ReferenceNumber a owl:Class ;
    rdfs:label "Reference Number" ;
    rdfs:comment "A reference number, such as an invoice number." .

:BusinessProcess a owl:Class ;
    rdfs:label "Business Process" ;
    rdfs:comment "A business process to which an invoice can be assigned." .

:ValidationConstraint a owl:Class ;
    rdfs:label "Validation Constraint" ;
    rdfs:comment "A constraint for validating EDIFACT documents, e.g., SHACL shapes." .

:MandatoryIdentifier a owl:Class ;
    rdfs:label "Mandatory Identifier" ;
    rdfs:comment "A mandatory identifier required by D96A." .

:PurchaseToPayOntologyReference a owl:Class ;
    rdfs:label "Purchase-to-Pay Ontology Reference" ;
    rdfs:comment "A reference to the Purchase-to-Pay Ontology (P2P-O)." .

:OrganizationRoleAssignment a owl:Class ;
    rdfs:label "Organization Role Assignment" ;
    rdfs:comment "A reified relationship linking an organization, its role, and the invoice context." .

#################################################################
# OBJECT PROPERTIES
#################################################################
:containsMessage a owl:ObjectProperty ;
    rdfs:label "contains message" ;
    rdfs:comment "Links an Interchange Envelope to its contained Message." ;
    rdfs:domain :InterchangeEnvelope ;
    rdfs:range :Message ;
    owl:FunctionalProperty .

:hasSegment a owl:ObjectProperty ;
    rdfs:label "has segment" ;
    rdfs:comment "Links a Message to its Segments." ;
    rdfs:domain :Message ;
    rdfs:range :Segment .

:hasSection a owl:ObjectProperty ;
    rdfs:label "has section" ;
    rdfs:comment "Links a Message to its header, detail, and summary sections." ;
    rdfs:domain :Message ;
    rdfs:range :CompositeDataElement .

:hasDataElement a owl:ObjectProperty ;
    rdfs:label "has data element" ;
    rdfs:comment "Links a Segment to its Composite Data Elements." ;
    rdfs:domain :Segment ;
    rdfs:range :CompositeDataElement .

:hasSimpleElement a owl:ObjectProperty ;
    rdfs:label "has simple element" ;
    rdfs:comment "Links a Composite Data Element to its Simple Data Elements." ;
    rdfs:domain :CompositeDataElement ;
    rdfs:range :SimpleDataElement .

:playsRole a owl:ObjectProperty ;
    rdfs:label "plays role" ;
    rdfs:comment "Indicates the role played by an Organization." ;
    rdfs:domain :Organization ;
    rdfs:range :AgentRole .

:hasRoleAssignment a owl:ObjectProperty ;
    rdfs:label "has role assignment" ;
    rdfs:comment "Links an Organization to its OrganizationRoleAssignment." ;
    rdfs:domain :Organization ;
    rdfs:range :OrganizationRoleAssignment .

:assignedRole a owl:ObjectProperty ;
    rdfs:label "assigned role" ;
    rdfs:comment "Links an OrganizationRoleAssignment to an AgentRole." ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :AgentRole .

:assignedInvoice a owl:ObjectProperty ;
    rdfs:label "assigned invoice" ;
    rdfs:comment "Links an OrganizationRoleAssignment to an Invoice." ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :Invoice .

:hasAddress a owl:ObjectProperty ;
    rdfs:label "has address" ;
    rdfs:comment "Links an Organization to its Address." ;
    rdfs:domain :Organization ;
    rdfs:range :Address .

:hasItem a owl:ObjectProperty ;
    rdfs:label "has item" ;
    rdfs:comment "Links an Invoice to its Items." ;
    rdfs:domain :Invoice ;
    rdfs:range :Item .

:hasPrice a owl:ObjectProperty ;
    rdfs:label "has price" ;
    rdfs:comment "Links an Item to its Price." ;
    rdfs:domain :Item ;
    rdfs:range :Price .

:hasValidationConstraint a owl:ObjectProperty ;
    rdfs:label "has validation constraint" ;
    rdfs:comment "Links an Invoice to its Validation Constraints." ;
    rdfs:domain :Invoice ;
    rdfs:range :ValidationConstraint .

:hasMandatoryIdentifier a owl:ObjectProperty ;
    rdfs:label "has mandatory identifier" ;
    rdfs:comment "Links an Invoice to its Mandatory Identifiers." ;
    rdfs:domain :Invoice ;
    rdfs:range :MandatoryIdentifier .

:assignedBusinessProcess a owl:ObjectProperty ;
    rdfs:label "assigned business process" ;
    rdfs:comment "Links an Invoice to a Business Process." ;
    rdfs:domain :Invoice ;
    rdfs:range :BusinessProcess .

:refersToP2POntology a owl:ObjectProperty ;
    rdfs:label "refers to P2P Ontology" ;
    rdfs:comment "Links an Invoice to a reference to the Purchase-to-Pay Ontology." ;
    rdfs:domain :Invoice ;
    rdfs:range :PurchaseToPayOntologyReference .

#################################################################
# DATA PROPERTIES
#################################################################
:hasGLN a owl:DatatypeProperty ;
    rdfs:label "has GLN" ;
    rdfs:comment "The Global Location Number of an Organization." ;
    rdfs:domain :Organization ;
    rdfs:range xsd:string ;
    owl:FunctionalProperty .

:itemNetPrice a owl:DatatypeProperty ;
    rdfs:label "item net price" ;
    rdfs:comment "The net price of an item." ;
    rdfs:domain :Item ;
    rdfs:range xsd:decimal .

:itemQuantity a owl:DatatypeProperty ;
    rdfs:label "item quantity" ;
    rdfs:comment "The quantity of an item." ;
    rdfs:domain :Item ;
    rdfs:range xsd:integer .

:itemTax a owl:DatatypeProperty ;
    rdfs:label "item tax" ;
    rdfs:comment "The tax amount for an item." ;
    rdfs:domain :Item ;
    rdfs:range xsd:decimal .

:hasReferenceNumber a owl:DatatypeProperty ;
    rdfs:label "has reference number" ;
    rdfs:comment "The reference number (such as invoice number) of an invoice." ;
    rdfs:domain :Invoice ;
    rdfs:range xsd:string .

:hasInvoiceAmount a owl:DatatypeProperty ;
    rdfs:label "has invoice amount" ;
    rdfs:comment "The total invoice amount." ;
    rdfs:domain :Invoice ;
    rdfs:range xsd:decimal .

:hasDate a owl:DatatypeProperty ;
    rdfs:label "has date" ;
    rdfs:comment "A date associated with an invoice (as a string)." ;
    rdfs:domain :Invoice ;
    rdfs:range xsd:string .

#################################################################
# CLASS AXIOMS
#################################################################
:AgentRole owl:disjointUnionOf ( :BuyerRole :DeliveryPartyRole ) .
:HeaderSection owl:disjointWith :DetailSection, :SummarySection .
:DetailSection owl:disjointWith :SummarySection .
:BuyerRole owl:disjointWith :DeliveryPartyRole .
:Segment owl:disjointWith :CompositeDataElement .
:CompositeDataElement owl:disjointWith :SimpleDataElement .

#################################################################
# RESTRICTIONS AND GCAs
#################################################################
:Invoice rdfs:subClassOf [ a owl:Restriction ; owl:onProperty :hasItem ; owl:someValuesFrom :Item ] .
:Organization rdfs:subClassOf [ a owl:Restriction ; owl:onProperty :hasGLN ; owl:allValuesFrom xsd:string ] .
:Item rdfs:subClassOf [ a owl:Restriction ; owl:onProperty :itemNetPrice ; owl:allValuesFrom xsd:decimal ] .
:Item rdfs:subClassOf [ a owl:Restriction ; owl:onProperty :itemQuantity ; owl:allValuesFrom xsd:integer ] .
:Item rdfs:subClassOf [ a owl:Restriction ; owl:onProperty :itemTax ; owl:allValuesFrom xsd:decimal ] .

#################################################################
# EQUIVALENCE AXIOMS
#################################################################
:BuyerRole owl:equivalentClass [ a owl:Restriction ; owl:onProperty :playsRole ; owl:allValuesFrom :BuyerRole ] .
:DeliveryPartyRole owl:equivalentClass [ a owl:Restriction ; owl:onProperty :playsRole ; owl:allValuesFrom :DeliveryPartyRole ] .

